    if (!found)
        return emptyArtifacts(memoID);
    const hash = hashText(transcript);
    if (found.sourceHash && hash && found.sourceHash !== hash) {
        // `ready` 只会变 `stale`，`none` 不变 —— 这就是「自动补空、不覆盖」的机制（规格 §19.11）。
        return {
