/** 给列表行算摘录（标题命中时不出摘录，与原生一致）。 */
export function withSnippet(memo, query, transcript) {
    if (!query)
        return memo;
    if (memo.title.toLowerCase().includes(query.toLowerCase()))
        return memo;
    const snippet = snippetOf(transcript, query);
    return snippet ? { ...memo, snippet } : memo;
