                setChrome(typeof state.hostChrome === 'boolean' ? state.hostChrome : state.transition === 'native');
            })
                .catch(() => undefined);
        };
        read();
        // 形态切换（sheet ↔ page ↔ fullscreen）会改变它，宿主在 `scene.changed` 上报形态时重读一次。
        const scene = bridge()?.scene;
