            cancelled = true;
            offs.forEach((off) => { try {
                if (typeof off === 'function')
                    off();
            }
            catch { /* 忽略 */ } });
        };
    }, []);
    const update = useCallback((items) => {
        const menu = bridge()?.menu;
        if (!menu || typeof menu.update !== 'function')
            return;
        try {
            const result = menu.update({ items });
            if (result && typeof result.catch === 'function')
