            return undefined;
        let cancelled = false;
        const offs = [];
        overlay.getState()
            .then((state) => { if (!cancelled)
            setRendered(!!(state && state.rendered)); })
            .catch(() => undefined);
        if (typeof overlay.on === 'function') {
            try {
                offs.push(overlay.on('invoke', (event) => handler.current(event || {})));
            }
            catch { /* 宿主未实现事件订阅 */ }
            try {
                // `rendered` 会**在挂载之后翻转**（形态切换、控制器重建都会重发 changed）。
                // 只判断启动那一刻，自绘控件就会永远缺席或永远多一份。
                offs.push(overlay.on('changed', (state) => {
                    if (!cancelled)
                        setRendered(!!(state && state.rendered));
                }));
            }
            catch { /* 同上 */ }
        }
        return () => {
            cancelled = true;
            offs.forEach((off) => { try {
                if (typeof off === 'function')
                    off();
            }
            catch { /* 忽略 */ } });
        };
    }, []);
    const update = useCallback((items) => {
        const api = bridge();
        const overlay = api && api.overlay;
        if (!overlay || typeof overlay.update !== 'function')
            return;
        try {
            const result = overlay.update({ items });
            if (result && typeof result.catch === 'function')
                result.catch(() => { });
        }
        catch { /* 展示态更新失败不该影响业务 */ }
    }, []);
    return { rendered, update };
}

// 应用级数据仓。**2.0.0 起只有一个数据源**：本应用自己的剪辑（`aibox.db` + applet 资源域）。
// 1.x 这里是「宿主录音库 + 本机剪辑」的合并视图，因为转写只有宿主那条线有；
// `aibox.audio.transcribe` 补上之后合并没有了理由，也就没有了「宿主模块不在场时半个应用变空」的风险。
import { useCallback, useEffect, useMemo, useState } from 'react';
import { clipToMemo, listClips, loadSetting, saveSetting } from './memos.js';
import { DEFAULT_SETTINGS } from './types.js';
const SETTINGS_KEY = 'settings';
export function useMemoStore() {
    const [ready, setReady] = useState(false);
    const [clips, setClips] = useState([]);
    const [settings, setSettings] = useState(DEFAULT_SETTINGS);
    const [tick, setTick] = useState(0);
    const refresh = useCallback(() => setTick((value) => value + 1), []);
    useEffect(() => {
        let cancelled = false;
        void (async () => {
            const [nextClips, stored] = await Promise.all([
                listClips(),
                loadSetting(SETTINGS_KEY, {}),
            ]);
            if (cancelled)
                return;
            setClips(nextClips);
            setSettings({ ...DEFAULT_SETTINGS, ...stored });
            setReady(true);
        })();
        return () => { cancelled = true; };
    }, [tick]);
    const memos = useMemo(() => clips.filter((clip) => !clip.isTrashed).map(clipToMemo).sort((a, b) => b.createdAt - a.createdAt), [clips]);
    const updateSettings = useCallback((patch) => {
        setSettings((current) => {
            const next = { ...current, ...patch };
            void saveSetting(SETTINGS_KEY, next);
            return next;
        });
    }, []);
    return {
        ready,
        memos,
        clips,
        settings,
        updateSettings,
        refresh,
    };
}

